package com.nbi.user.model;

import java.time.Instant;

// ENTITY: server controls id, passwordHash, createdAt, role. Stays internal.
public class User {
    private String id;
    private String name;
    private String email;
    private String passwordHash; // secret
    private String role;         // server-controlled
    private Instant createdAt;   // server-generated

    public User(String id, String name, String email, String passwordHash) {
        this.id = id; this.name = name; this.email = email;
        this.passwordHash = passwordHash; this.role = "CUSTOMER";
        this.createdAt = Instant.now();
    }
    public String getId() { return id; }
    public String getName() { return name; }
    public String getEmail() { return email; }
    public String getPasswordHash() { return passwordHash; }
    public String getRole() { return role; }
    public Instant getCreatedAt() { return createdAt; }
}
```

