// ─── File: src/main/java/com/nbi/user/service/UserService.java ───
package com.nbi.user.service;

import com.nbi.user.dto.*;
import com.nbi.user.model.User;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class UserService {
    private final Map<String, User> repo = new HashMap<>();

    // Map REQUEST DTO → entity. Server sets id/role/createdAt — client cannot.
    public UserResponse create(CreateUserRequest req) {
        String id = "USR-" + UUID.randomUUID().toString().substring(0, 6);
        User entity = new User(id, req.name(), req.email(), hash(req.password()));
        repo.put(id, entity);
        return toResponse(entity); // conversion in the SERVICE layer
    }

    public Optional<UserResponse> find(String id) {
        return Optional.ofNullable(repo.get(id)).map(this::toResponse);
    }

    // Map entity → RESPONSE DTO. passwordHash never copied → never leaks.
    private UserResponse toResponse(User u) {
        return new UserResponse(u.getId(), u.getName(), u.getEmail(), u.getRole(), u.getCreatedAt());
    }

    private String hash(String raw) { return "hash$" + Integer.toHexString(raw.hashCode()); }
}
```

```java
// ─── File: src/main/java/com/nbi/user/controller/UserController.java ───
package com.nbi.user.controller;

import com.nbi.user.dto.*;
import com.nbi.user.service.UserService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    private final UserService service;
    public UserController(UserService service) { this.service = service; }

    // Thin adapter: DTO in, DTO out. Never sees the entity. No mapping here.
    @PostMapping
    public ResponseEntity<UserResponse> create(@Valid @RequestBody CreateUserRequest req) {
        UserResponse resp = service.create(req);
        return ResponseEntity.created(URI.create("/api/v1/users/" + resp.id())).body(resp);
    }

    @GetMapping("/{id}")
    public ResponseEntity<UserResponse> get(@PathVariable String id) {
        return service.find(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());
    }
}
```
